# Rodada "simplificar": primeiro acesso em 3 passos, menu enxuto, abas agrupadas e busca única
from t40_lib import *
import json
P,e=open_h('exec_simp@totvs.com.br')
tx=lambda: ev(P,"document.querySelector('#app').innerText")
ev(P,"S.clients={};['onb.fim','onb.semana','onb.cliente'].forEach(k=>{try{lsSet(k,'')}catch(e){}});UI.view='geral';render();0"); P.wait_for_timeout(400)
ob=lambda: ev(P,"document.querySelector('#onb')?.innerText||''")
# 1) primeiro acesso
ck('primeiro acesso: quadro "Comece em 3 passos", 0 de 3', 'Comece em 3 passos' in ob() and '0 de 3' in ob() and ev(P,"document.querySelectorAll('#onb li').length")==3, ob()[:120])
ck('só o passo 1 está liberado e em destaque', ev(P,"[...document.querySelectorAll('#onb [data-a=onbIr]')].map(b=>[b.disabled,b.classList.contains('pri')]).join('|')")=='false,true|true,false|true,false')
ck('itens opcionais (IA, ficha, lembrete) não aparecem antes dos 3 passos', 'chave de IA' not in ob() and 'lembrete' not in ob())
P.click('#onb [data-a=onbIr][data-i="0"]'); P.wait_for_timeout(400)
ck('passo 1 leva para Carteira & MRR (subir planilha)', ev(P,"UI.view")=='mrr' and ev(P,"!!document.querySelector('input[type=file]')"))
ev(P,"""(()=>{const mk=(k,name,cod,mrr)=>{S.clients[k]={key:k,name,code:cod,cnpj:'',productsRaw:'Protheus',segment:'Manufatura',fichas:[],docs:[],mgmt:{},act:{},opps:[],src:{row:1},emp:{cod,razao:name,mrrC:mrr,mrrP:mrr,uvp:'2025-01-10',uvs:'2026-08-01',sit:'Ativo',prod:'Protheus',hist:[]},gst:{interacoes:[]}};runAnalysis(S.clients[k]);};mk('sa','Alfa Metalúrgica','T10001',30000);mk('sb','Beta Logística','T10002',8000);S.meta.emp={dataBase:'2026-11-10',cfg:{limiarMrr:20000,limiarDias:365,baseRecencia:'produto'},snaps:[]};S.clients.sa.gst.proximaAcao='Apresentar proposta de sustentação';S.clients.sa.gst.dataAcao='2026-11-20';UI.view='geral';render();return 0})()"""); P.wait_for_timeout(400)
ck('com carteira: 1 de 3 e o passo 2 vira o destaque', '1 de 3' in ob() and ev(P,"document.querySelector('#onb [data-a=onbIr].pri').dataset.i")=='1')
P.click('#onb [data-a=onbIr][data-i="1"]'); P.wait_for_timeout(500)
ck('passo 2 abre o Plano da semana e é marcado pelo uso da tela', ev(P,"UI.view")=='mrr' and ev(P,"UI.emp.tab")=='semana' and ev(P,"lsGet('onb.semana')")=='1')
ev(P,"UI.sel='sa';UI.view='cliente';UI.ctab='raiox';render();UI.view='geral';render();0"); P.wait_for_timeout(400)
ck('abrir um cliente conclui o passo 3; restam só os opcionais em uma linha', ev(P,"lsGet('onb.cliente')")=='1' and ('Tudo pronto' in ob() or ob()=='') and 'Comece em 3 passos' not in ob(), ob()[:120])
P.click('#onb [data-a=onbFim]') if ev(P,"!!document.querySelector('#onb')") else None; P.wait_for_timeout(200)
ck('ocultar remove o quadro', ev(P,"document.querySelector('#onb')")==None)
# 2) menu
tops=json.loads(ev(P,"JSON.stringify(NAV.filter(x=>x[0]!=='adm').map(x=>x[1]))"))
ck('menu com 8 entradas principais; suporte agrupado em "Mais ferramentas"', len(tops)==8 and 'Mais ferramentas' in tops and not any(x in tops for x in ['Consulta de CNPJ','Integrações','Pendências documentais']), tops)
ev(P,"UI.view='cnpj';render();0"); P.wait_for_timeout(300)
ck('subitens acessíveis e grupo ativo ao entrar em Consulta de CNPJ', ev(P,"[...document.querySelectorAll('#nav .sb-item.sub')].map(b=>b.dataset.v).join()")=='pend,cnpj,integra' and ev(P,"document.querySelector('#nav .sb-item.sub.on').dataset.v")=='cnpj')
ck('todas as telas continuam alcançáveis pelo menu', all(ev(P,"NAV.some(x=>x[0]==='%s'||x[3].some(s=>s[0]==='%s'))"%(v,v)) for v in ['geral','mrr','forecast','clientes','segmentos','consol','oport','plano','mercado','solucoes','portfolio','refs','importar','pend','cnpj','integra','conta','ia','dados','criterios','base']))
# 3) Carteira & MRR: 5 abas
ev(P,"UI.view='mrr';UI.emp.tab='painel';render();0"); P.wait_for_timeout(400)
ck('Carteira & MRR: barra com 5 abas', ev(P,"[...document.querySelectorAll('.em-v > .ctabs button')].map(b=>b.innerText.trim().replace(/\\s*\\d+$/,'')).join('|')")=='Painel|Plano da semana|Análises|Qualidade|Importar & histórico', ev(P,"[...document.querySelectorAll('.em-v > .ctabs button')].map(b=>b.innerText).join('|')"))
t1=tx(); ev(P,"UI.emp.tab='visao';render();0"); P.wait_for_timeout(300)
ck('Painel reúne o painel executivo e a visão geral; chave antiga "visao" cai no mesmo lugar', tx()==t1 and ev(P,"document.querySelector('.em-v > .ctabs button.on').dataset.v")=='painel')
P.click('.em-v > .ctabs [data-v=recencia]'); P.wait_for_timeout(300)
ck('Análises: subnível com Última venda, Produtos e Grupos', ev(P,"[...document.querySelectorAll('.em-sub button')].map(b=>b.innerText.trim()).join('|')")=='Última venda|Produtos|Grupos' and ev(P,"document.querySelector('.em-sub button.on').dataset.v")=='recencia')
P.click('.em-sub [data-v=grupos]'); P.wait_for_timeout(300)
ck('subaba Grupos abre e "Análises" continua marcada', ev(P,"UI.emp.tab")=='grupos' and ev(P,"document.querySelector('.em-v > .ctabs button.on').dataset.v")=='recencia')
P.click('.em-v > .ctabs [data-v=semana]'); P.wait_for_timeout(300)
ck('fora de Análises o subnível some', ev(P,"document.querySelector('.em-sub')")==None)
# 4) ficha: grupos
ev(P,"UI.sel='sa';UI.view='cliente';UI.ctab='raiox';render();0"); P.wait_for_timeout(400)
ck('ficha: 3 grupos e só as abas do grupo ativo', ev(P,"[...document.querySelectorAll('.cgrp button')].map(b=>b.innerText.trim()).join('|')")=='Preparar a conversa|Contrato e ambiente|Acompanhar' and ev(P,"[...document.querySelectorAll('.ctabs button')].map(b=>b.dataset.v).join()")=='raiox,resumo,diagnostico,briefing,portfolio')
P.click('.cgrp [data-g=contrato]'); P.wait_for_timeout(300)
ck('trocar de grupo abre a primeira aba dele', ev(P,"UI.ctab")=='cadastro' and ev(P,"document.querySelectorAll('.ctabs button').length")==7 and ev(P,"document.querySelector('.cgrp button.on').dataset.g")=='contrato')
ev(P,"UI.ctab='reuniao';render();0"); P.wait_for_timeout(300)
ck('aba aberta por atalho marca o grupo certo', ev(P,"document.querySelector('.cgrp button.on').dataset.g")=='acompanhar' and ev(P,"document.querySelector('.ctabs button.on').dataset.v")=='reuniao')
ck('todas as 15 abas pertencem a algum grupo', ev(P,"CTABS.every(t=>CGRUPOS.some(g=>g[2].includes(t[0])))") and ev(P,"CTABS.length")==sum(json.loads(ev(P,"JSON.stringify(CGRUPOS.map(g=>g[2].length))"))))
# 5) busca única
def busca(q):
    P.fill('#gq',q); P.wait_for_timeout(350); return ev(P,"document.querySelector('#gres').innerText")
g=busca('alfa'); ck('busca: cliente continua primeiro', ev(P,"document.querySelector('#gres .gr').dataset.a")=='gsOpen' and 'Alfa Metalúrgica' in g)
g=busca('configurador'); ck('busca: acha solução', 'SOLUÇÕES' in g.upper() and 'Configurador de Tributos' in g and 'onde posso vender' in g, g[:150])
P.click('#gres [data-a=gsSol]'); P.wait_for_timeout(400)
ck('solução na busca abre "Onde posso vender" e limpa o campo', ev(P,"UI.view")=='portfolio' and 'Onde posso vender: Configurador' in tx() and ev(P,"document.querySelector('#gq').value")=='' and ev(P,"document.querySelector('#gres').hidden"))
g=busca('sustentação'); ck('busca: acha ação da conta', 'Apresentar proposta de sustentação' in g and 'Alfa Metalúrgica' in g)
P.click('#gres [data-a=gsAcao]'); P.wait_for_timeout(400)
ck('ação abre a ficha na Gestão da conta', ev(P,"UI.view")=='cliente' and ev(P,"UI.ctab")=='gestao' and ev(P,"UI.sel")=='sa')
g=busca('forecast'); ck('busca: acha tela', 'IR PARA' in g.upper() and 'Meu Forecast' in g)
P.click('#gres [data-a=gsTela]'); P.wait_for_timeout(400)
ck('tela na busca navega', ev(P,"UI.view")=='forecast')
g=busca('zzqqxx'); ck('busca sem resultado: mensagem única', 'Nada encontrado' in g)
P.fill('#gq','alfa'); P.wait_for_timeout(300); P.press('#gq','Enter'); P.wait_for_timeout(400)
ck('Enter abre o primeiro resultado (cliente)', ev(P,"UI.view")=='cliente' and ev(P,"UI.sel")=='sa')
ev(P,"S.clients={};S.meta.emp=null;UI.view='geral';render();0")
ck('sem erro de script', not e, e[:2])
print('FALHAS:',len(F)); [print(' -',x) for x in F]; p.stop()
